mapper.update:
UPDATE wkf_supply_request
SET status_enum = 'PENDING_APPROVAL',
    approver_id = #{approverId},
    applicant_id = #{applicantId},
    apply_time = #{applyTime},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE bus_no = #{busNo}
  AND type_enum = #{typeEnum}
  AND status_enum = #{currentStatus}
  AND is_deleted = 0

UPDATE wkf_supply_request
SET status_enum = 'WITHDRAW',
    approver_id = NULL,
    approval_time = NULL,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE bus_no = #{busNo}
  AND type_enum = #{typeEnum}
  AND status_enum = #{currentStatus}
  AND is_deleted = 0

UPDATE wkf_supply_request
SET status_enum = 'AGREE',
    approver_id = #{approverId},
    approval_time = #{approvalTime},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE bus_no = #{busNo}
  AND type_enum = #{typeEnum}
  AND status_enum = #{currentStatus}
  AND is_deleted = 0

UPDATE wkf_supply_request
SET status_enum = 'REJECT',
    approver_id = #{approverId},
    approval_time = #{approvalTime},
    reason = #{reason},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE bus_no = #{busNo}
  AND type_enum = #{typeEnum}
  AND status_enum = #{currentStatus}
  AND is_deleted = 0
